{"packet_id": "D067-04", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Evictions from owner-occupied two- and three-family dwellings", "requirement": "In landlord-occupied two- and three-family dwellings, the landlord may evict only for the listed grounds and must give three months’ notice to quit for at-will or year-to-year tenancies and one month’s notice for month-to-month tenancies.", "key_value": "3 months’ notice to quit for at-will or year-to-year tenancies; 1 month for month-to-month tenancies", "coverage_conditions": "Tenants in landlord-occupied two- and three-family dwellings; grounds include holdover, nonpayment, disorderly conduct, willful damage, rule violations and lease breaches.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": 3, "owner_dependent": true, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.2", "quoted_span": "Tenants of landlord-occupied two- and three-family dwellings can be removed only when
a court issues an order for eviction. However, in these cases, the landlord must prove that the tenant
(a) is staying after the expiration of the term of the lease, (b) is staying after a failure to pay rent,", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-04", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Penalties for misusing personal-occupancy and retirement evictions", "requirement": "A landlord who evicts for personal occupancy must occupy the unit at least six months; one who removes property from residential use must keep it non-residential for five years.", "key_value": "3 times damages plus attorney fees and costs", "coverage_conditions": "Landlords who recovered possession for their own personal occupancy or who boarded up, demolished or permanently retired residential property.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "Three times the damages plus attorney fees and costs; for unlawful residential reuse also a civil penalty up to $10,000.00 per violation and no registration as a planned real estate development for five years.", "effective_date": null, "citation": "N.J.S.A. 2A:18-61.6", "quoted_span": "When a tenant vacates a dwelling unit after having been given notice that the  landlord
wishes to personally occupy the unit the landlord must occupy the unit for at least six (6) months.
If instead the landlord permits personal occupancy of the unit by another tenant or registration of
conversion of the property to a condominium or cooperative, the landlord is liable to the former
tenant for three (3) times the damages suffered plus attorney fees and costs  (N.J.S.A. 2A:18-
61.6(a)).", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-04", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Reprisal eviction and lease-change ban", "requirement": "A landlord may not evict, substantially alter a lease or refuse to renew because a tenant asserted lease or housing-code rights, complained to a government agency, joined a tenant organization, or refused retaliatory lease changes.", "key_value": null, "coverage_conditions": "All rental properties used for dwelling purposes, including mobile homes.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "Owner-occupied two- or three-family dwellings.", "penalty": "The tenant may sue the landlord for damages in a civil action.", "effective_date": null, "citation": "N.J.S.A. 2A:42-10.10", "quoted_span": "A landlord cannot take reprisal action against a tenant by eviction, substantial alteration of
a lease or its terms, or refusal to renew a lease when a tenant exercises certain civil rights (N.J.S.A.
2A:42-10.10).  The law against reprisal applies to all rental properties used for dwelling purposes,
including mobile homes, except owner-occupied two- or three-family dwellings.", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-04", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Senior citizens and disabled protected tenancy in conversions", "requirement": "Qualifying senior, permanently disabled or certain disabled veteran tenants in a building converted to condominium, cooperative or fee simple ownership may be protected from eviction for up to 40 years.", "key_value": "40 years’ protection; income at or below 3 times county average per person income or $50,000.00", "coverage_conditions": "Tenants at least 62 years old, permanently disabled, or honorably discharged and at least 60% disabled, who lived in the building at least one year before the conversion recording.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Applies to buildings converted or being converted to condominium, cooperative or fee simple ownership."}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.28", "quoted_span": "Tenants may be protected from eviction for 40 years
if their family income is not more than three (3) times the average per person income in their
county or $50,000.00, whichever  is greater (N.J.S.A. 2A:18-61.28).", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-04", "doc_id": "D067", "jurisdiction": "NJ", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Increases above rent control or unconscionable increases prohibited", "requirement": "A landlord may not impose a rent increase that exceeds any rent control or rent leveling ordinance, or, where rent control does not apply, an unreasonable or unconscionable rent increase.", "key_value": null, "coverage_conditions": null, "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "NJ DCA landlord-tenant information, prohibited landlord conduct toward tenants", "quoted_span": "An increase in rent in excess of any rent control or rent leveling ordinance, or if the property
is not subject to rent control, an unreasonable or unconscionable rent increase.", "interaction": null, "confidence": 0.6, "conflict_flag": false, "conflict_note": null}
